//
//  OllamaService.swift
//  SwiftMandarin
//
//  Service for interacting with local Ollama models as an alternative to Apple Intelligence.
//  Provides model discovery, chat completion, and structured output generation.
//

import Foundation
import SwiftUI
import Ollama

// MARK: - Ollama Model Info

/// Represents an available Ollama model with its metadata
struct OllamaModelInfo: Identifiable, Hashable, Codable {
    var id: String { name }
    let name: String
    let size: Int64
    let parameterSize: String
    let family: String
    let supportsThinking: Bool
    let supportsTools: Bool

    /// Human-readable size string
    var sizeString: String {
        let formatter = ByteCountFormatter()
        formatter.countStyle = .file
        return formatter.string(fromByteCount: size)
    }
}

// MARK: - Ollama Service

/// Service that provides access to local Ollama models for AI-powered features
@Observable
@MainActor
final class OllamaService {

    static let shared = OllamaService()

    // MARK: - Properties

    /// The Ollama client instance
    private var client: Ollama.Client

    /// Available models discovered from Ollama
    private(set) var availableModels: [OllamaModelInfo] = []

    /// Whether Ollama server is reachable
    private(set) var isConnected: Bool = false

    /// Last connection error if any
    private(set) var connectionError: String?

    /// Whether we're currently loading models
    private(set) var isLoadingModels: Bool = false

    /// The Ollama server host URL
    var hostURL: URL {
        get { client.host }
        set { 
            client = Ollama.Client(host: newValue)
            // Re-check connection when host changes
            Task { await checkConnection() }
        }
    }

    // MARK: - Configuration

    /// Default options for gpt-oss 20b model with extended context and reasoning
    static let defaultOptions: [String: Ollama.Value] = [
        "num_ctx": .int(128000),           // 128k context window
        "temperature": .double(0.7),        // Balanced creativity
        "top_p": .double(0.9),              // Nucleus sampling
        "repeat_penalty": .double(1.1),     // Reduce repetition
        "num_predict": .int(-1),            // No limit on tokens
    ]

    /// Options optimized for reasoning tasks
    static let reasoningOptions: [String: Ollama.Value] = [
        "num_ctx": .int(128000),            // 128k context window
        "temperature": .double(0.3),         // More deterministic for reasoning
        "top_p": .double(0.95),
        "repeat_penalty": .double(1.05),
        "num_predict": .int(-1),
    ]

    // MARK: - Initialization

    private init() {
        // Initialize with default localhost
        self.client = Ollama.Client.default
    }

    // MARK: - Connection Management

    /// Check if Ollama server is reachable
    func checkConnection() async {
        do {
            _ = try await client.version()
            isConnected = true
            connectionError = nil
        } catch {
            isConnected = false
            connectionError = error.localizedDescription
        }
    }

    /// Refresh the list of available models from Ollama
    func refreshModels() async {
        isLoadingModels = true
        defer { isLoadingModels = false }

        do {
            let response = try await client.listModels()

            // Get detailed info for each model to check capabilities
            var models: [OllamaModelInfo] = []
            for model in response.models {
                // Skip any discovered model whose name isn't a valid Ollama model ID
                // rather than force-unwrapping (which would crash the whole refresh).
                guard let modelID = Ollama.Model.ID(rawValue: model.name) else {
                    continue
                }

                // Try to get capabilities for each model
                var supportsThinking = false
                var supportsTools = false

                do {
                    let details = try await client.showModel(modelID)
                    supportsThinking = details.capabilities.contains(.thinking)
                    supportsTools = details.capabilities.contains(.tools)
                } catch {
                    // Ignore errors fetching details, use defaults
                }

                let info = OllamaModelInfo(
                    name: model.name,
                    size: model.size,
                    parameterSize: model.details.parameterSize,
                    family: model.details.family,
                    supportsThinking: supportsThinking,
                    supportsTools: supportsTools
                )
                models.append(info)
            }

            availableModels = models.sorted { $0.name < $1.name }
            isConnected = true
            connectionError = nil
        } catch {
            availableModels = []
            isConnected = false
            connectionError = error.localizedDescription
        }
    }

    // MARK: - Chat Completion

    /// Generate a chat completion with the specified model
    /// - Parameters:
    ///   - model: The model name to use
    ///   - systemPrompt: System instructions for the model
    ///   - userPrompt: The user's message
    ///   - enableThinking: Whether to enable thinking/reasoning mode
    ///   - options: Additional model options
    /// - Returns: The model's response content
    func chat(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        enableThinking: Bool = true,
        options: [String: Ollama.Value]? = nil
    ) async throws -> (content: String, thinking: String?) {
        guard let modelID = Ollama.Model.ID(rawValue: model) else {
            throw OllamaServiceError.modelNotFound(model)
        }

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        let response = try await client.chat(
            model: modelID,
            messages: messages,
            options: options ?? Self.defaultOptions,
            think: enableThinking,
            keepAlive: .minutes(10)
        )

        return (content: response.message.content, thinking: response.message.thinking)
    }

    /// Generate a streaming chat completion
    func chatStream(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        enableThinking: Bool = true,
        options: [String: Ollama.Value]? = nil
    ) throws -> AsyncThrowingStream<Ollama.Client.ChatResponse, Error> {
        guard let modelID = Ollama.Model.ID(rawValue: model) else {
            throw OllamaServiceError.modelNotFound(model)
        }

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        return try client.chatStream(
            model: modelID,
            messages: messages,
            options: options ?? Self.defaultOptions,
            think: enableThinking,
            keepAlive: .minutes(10)
        )
    }

    // MARK: - Structured Output Generation

    /// Generate a structured JSON response matching a schema
    /// - Parameters:
    ///   - model: The model name to use
    ///   - systemPrompt: System instructions
    ///   - userPrompt: User message
    ///   - schema: JSON schema for the expected output
    ///   - enableThinking: Whether to enable thinking mode
    /// - Returns: The JSON string response
    func generateStructured(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        schema: Ollama.Value,
        enableThinking: Bool = true
    ) async throws -> String {
        guard let modelID = Ollama.Model.ID(rawValue: model) else {
            throw OllamaServiceError.modelNotFound(model)
        }

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        let response = try await client.chat(
            model: modelID,
            messages: messages,
            options: Self.reasoningOptions,
            format: schema,
            think: enableThinking,
            keepAlive: .minutes(10)
        )

        return response.message.content
    }

    /// Generate structured output and decode it to a Codable type
    func generateAndDecode<T: Codable>(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        type: T.Type,
        enableThinking: Bool = true
    ) async throws -> T {
        // Build JSON schema from type (simplified approach)
        let jsonString = try await generateStructured(
            model: model,
            systemPrompt: systemPrompt,
            userPrompt: userPrompt,
            schema: "json",
            enableThinking: enableThinking
        )

        guard let data = jsonString.data(using: .utf8) else {
            throw OllamaServiceError.invalidResponse("Response is not valid UTF-8")
        }

        do {
            return try JSONDecoder().decode(T.self, from: data)
        } catch {
            throw OllamaServiceError.decodingFailed("Failed to decode response: \(error.localizedDescription)")
        }
    }

    // MARK: - Translation

    /// Translate text using Ollama
    /// - Parameters:
    ///   - text: The text to translate
    ///   - sourceIsChinese: Whether the source is Chinese (true) or English (false)
    ///   - model: The model to use
    /// - Returns: The translated text
    func translate(
        _ text: String,
        sourceIsChinese: Bool,
        model: String
    ) async throws -> String {
        let systemPrompt = AITranslationPromptBuilder.instructions
        let userPrompt = AITranslationPromptBuilder.request(
            text: text,
            sourceIsChinese: sourceIsChinese
        )

        let (content, _) = try await chat(
            model: model,
            systemPrompt: systemPrompt,
            userPrompt: userPrompt,
            enableThinking: false, // Translation doesn't need reasoning
            options: Self.defaultOptions
        )

        return content.trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

// MARK: - Errors

enum OllamaServiceError: LocalizedError {
    case notConnected
    case modelNotFound(String)
    case invalidResponse(String)
    case decodingFailed(String)
    case generationFailed(String)

    var errorDescription: String? {
        switch self {
        case .notConnected:
            return "Ollama server is not connected. Please ensure Ollama is running."
        case .modelNotFound(let name):
            return "Model '\(name)' not found. Please pull the model first."
        case .invalidResponse(let detail):
            return "Invalid response from Ollama: \(detail)"
        case .decodingFailed(let detail):
            return "Failed to decode response: \(detail)"
        case .generationFailed(let detail):
            return "Generation failed: \(detail)"
        }
    }
}

//
//  WordTranslationService.swift
//  SwiftMandarin
//
//  Service for translating individual words/phrases using Apple's Translation
//  API (iOS 18+/macOS 15+). On older systems it falls back to the configured
//  AI provider, so word lookups keep working on iOS 17.
//

import Foundation
import Translation

/// Service for translating individual words using Apple's Translation API
@Observable
final class WordTranslationService {

    static let shared = WordTranslationService()

    /// Cache for translated words to avoid repeated API calls
    private var translationCache: [String: String] = [:]

    private init() {}

    // MARK: - Public Methods

    /// Translate a single word or phrase from Chinese to English
    /// Uses installed language packs (requires languages to be pre-downloaded)
    /// - Parameter word: The Chinese word/phrase to translate
    /// - Returns: The English translation
    func translateToEnglish(_ word: String) async throws -> String {
        // Check cache first
        let cacheKey = "zh-en:\(word)"
        if let cached = translationCache[cacheKey] {
            return cached
        }

        let translation = try await systemOrAITranslate(word, sourceIsChinese: true)
        translationCache[cacheKey] = translation
        return translation
    }

    /// Translate a single word or phrase from English to Chinese
    /// Uses installed language packs (requires languages to be pre-downloaded)
    /// - Parameter word: The English word/phrase to translate
    /// - Returns: The Chinese translation
    func translateToChinese(_ word: String) async throws -> String {
        // Check cache first
        let cacheKey = "en-zh:\(word)"
        if let cached = translationCache[cacheKey] {
            return cached
        }

        let translation = try await systemOrAITranslate(word, sourceIsChinese: false)
        translationCache[cacheKey] = translation
        return translation
    }

    /// Translate a word with automatic language detection
    /// - Parameters:
    ///   - word: The word to translate
    ///   - sourceIsChinese: Whether the source word is Chinese
    /// - Returns: The translated word in the opposite language
    func translate(_ word: String, sourceIsChinese: Bool) async throws -> String {
        if sourceIsChinese {
            return try await translateToEnglish(word)
        } else {
            return try await translateToChinese(word)
        }
    }

    /// Batch translate multiple words (more efficient for multiple lookups)
    /// - Parameters:
    ///   - words: Array of words to translate
    ///   - sourceIsChinese: Whether source words are Chinese
    /// - Returns: Dictionary mapping original words to translations
    func translateBatch(_ words: [String], sourceIsChinese: Bool) async throws -> [String: String] {
        var results: [String: String] = [:]
        var wordsToTranslate: [String] = []

        // Check cache first
        let cachePrefix = sourceIsChinese ? "zh-en:" : "en-zh:"
        for word in words {
            let cacheKey = "\(cachePrefix)\(word)"
            if let cached = translationCache[cacheKey] {
                results[word] = cached
            } else {
                wordsToTranslate.append(word)
            }
        }

        // Return early if all words were cached
        if wordsToTranslate.isEmpty {
            return results
        }

        if #available(iOS 26.0, macOS 26.0, *) {
            // Create translation session using installed languages
            let session = TranslationSession(
                installedSource: sourceIsChinese ? Locale.Language(identifier: "zh-Hans") : Locale.Language(identifier: "en"),
                target: sourceIsChinese ? Locale.Language(identifier: "en") : Locale.Language(identifier: "zh-Hans")
            )

            // Create batch requests with client identifiers for matching
            var requests: [TranslationSession.Request] = []
            for (index, word) in wordsToTranslate.enumerated() {
                requests.append(TranslationSession.Request(
                    sourceText: word,
                    clientIdentifier: "\(index)"
                ))
            }

            // Perform batch translation
            let responses = try await session.translations(from: requests)

            // Process responses and update cache
            for response in responses {
                if let clientId = response.clientIdentifier,
                   let index = Int(clientId),
                   index < wordsToTranslate.count {
                    let originalWord = wordsToTranslate[index]
                    let translation = response.targetText

                    results[originalWord] = translation
                    translationCache["\(cachePrefix)\(originalWord)"] = translation
                }
            }
        } else {
            // Pre-iOS 26: translate sequentially through the configured AI
            // provider (each result is cached, so repeat lookups are free).
            for word in wordsToTranslate {
                let translation = try await AIWordExplanationService.shared
                    .translateWithProvider(word, sourceIsChinese: sourceIsChinese)
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                guard !translation.isEmpty else { continue }
                results[word] = translation
                translationCache["\(cachePrefix)\(word)"] = translation
            }
        }

        return results
    }

    /// Clear the translation cache
    func clearCache() {
        translationCache.removeAll()
    }

    /// Get cached translation if available
    func getCachedTranslation(for word: String, sourceIsChinese: Bool) -> String? {
        let cacheKey = sourceIsChinese ? "zh-en:\(word)" : "en-zh:\(word)"
        return translationCache[cacheKey]
    }

    // MARK: - Backend Selection

    /// Apple's on-device Translation API where available (iOS 26+/macOS 26+;
    /// the standalone session initializer is newer than the SwiftUI task API),
    /// otherwise the user's configured AI provider.
    private func systemOrAITranslate(_ text: String, sourceIsChinese: Bool) async throws -> String {
        if #available(iOS 26.0, macOS 26.0, *) {
            let session = TranslationSession(
                installedSource: Locale.Language(identifier: sourceIsChinese ? "zh-Hans" : "en"),
                target: Locale.Language(identifier: sourceIsChinese ? "en" : "zh-Hans")
            )
            let response = try await session.translate(text)
            return response.targetText
        } else {
            return try await AIWordExplanationService.shared
                .translateWithProvider(text, sourceIsChinese: sourceIsChinese)
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }
    }
}

