        } catch let failure as CheckFailure {
            fputs("AI prompt contract check failed: \(failure.message)\n", stderr)
            exit(1)
        } catch {
            fputs("AI prompt contract checks failed: \(error)\n", stderr)
            exit(1)
        }
    }
}
