//
//  AIWordExplanationService.swift
//  SwiftMandarin
//
//  Service for generating detailed word explanations using Apple Intelligence
//  (Foundation Models framework) or Ollama for on-device AI processing
//

import Foundation
import SwiftUI
import Ollama

#if canImport(FoundationModels)
import FoundationModels
#endif

// MARK: - Explanation Direction

/// Direction of one explanation request. The explanation is always written in
/// the learner's NATIVE language (= the interface language), and the word's
/// own language is detected from its content, since headwords can be either
/// language depending on the learning direction.
struct ExplanationDirection: Equatable {
    let wordIsChinese: Bool
    let explainInChinese: Bool

    @MainActor
    static func current(forWord word: String) -> ExplanationDirection {
        ExplanationDirection(
            wordIsChinese: word.containsCJK,
            explainInChinese: LocalizationManager.shared.nativeIsChinese
        )
    }

    /// Human-readable name of the word's language, for prompts.
    var wordLanguageName: String { wordIsChinese ? "Mandarin Chinese" : "English" }

    /// Human-readable name of the explanation language, for prompts.
    var explanationLanguageName: String { explainInChinese ? "Simplified Chinese (简体中文)" : "English" }

    /// Distinguishes cached explanations per direction so toggling the
    /// interface language regenerates rather than serving the old language.
    var cacheToken: String { "\(wordIsChinese ? "zh" : "en")>\(explainInChinese ? "zh" : "en")" }

    /// Provider-neutral language context for the shared prompt contract.
    var promptContext: AIExplanationPromptContext {
        AIExplanationPromptContext(
            wordLanguageName: wordLanguageName,
            explanationLanguageName: explanationLanguageName,
            wordIsChinese: wordIsChinese,
            explanationIsSameLanguage: wordIsChinese == explainInChinese
        )
    }
}

// MARK: - Word Explanation Models

/// Structured response for a detailed word explanation.
/// Uses @Generable for type-safe structured generation from Apple Intelligence.
/// Field semantics are direction-neutral: the example/collocation text is in
/// the word's own language and all explanatory text is in the learner's
/// native language, both of which are stated in the session instructions.
#if canImport(FoundationModels)
@available(iOS 26.0, macOS 26.0, *)
@Generable
struct WordExplanation {
    @Guide(description: "In the learner's native language: when the languages differ, the closest natural translation for the selected sense; when they match, a non-circular plain-language definition or paraphrase. Follow it with the semantic essence in at most two short, concrete sentences; do not list unrelated dictionary senses")
    let definition: String

    @Guide(description: "The precise part of speech for the selected sense, written in the learner's native language; include a compact behavior label such as separable, transitive, countable, or classifier only when relevant")
    let partOfSpeech: String

    @Guide(description: "In the learner's native language: for Chinese, use one compact line per character or bound morpheme, giving a core meaning only when it contributes semantically and otherwise identifying a phonetic, transliterated, grammatical, fossilized, or uncertain role; add a localized Together bridge to the lexicalized whole without inventing etymology, then give register, feeling, and one practical contrast. For English, discuss genuine morphology only when useful, otherwise move directly to register and contrast without repeating the definition.")
    let nuances: String

    @Guide(description: "In the learner's native language: only grammar that changes how the learner can use this sense, with one reusable construction and its key constraint; return an empty string when there is no useful special grammar")
    let grammarUsage: String

    @Guide(description: "Two or three concise, concrete mini-situations where a native speaker would naturally choose this sense, written in the learner's native language", .maximumCount(3))
    let usageContexts: [String]

    @Guide(description: "One or two short, idiomatic, semantically distinct examples of the selected lexeme; at least one must contain the exact headword, while another may use a natural inflected or separated form; add a third only for a genuinely different construction", .maximumCount(3))
    let exampleSentences: [ExampleSentence]

    @Guide(description: "Zero to two genuine near-synonyms in the same language as the headword; an empty list is better than a weak or invented relation", .maximumCount(2))
    let synonyms: [RelatedWord]

    @Guide(description: "Zero or one established lexical opposite in the same language as the headword; return an empty list when no true opposite exists", .maximumCount(1))
    let antonyms: [RelatedWord]

    @Guide(description: "Zero to two high-confidence idiomatic phrases using the selected lexeme; at least one returned phrase must contain the exact headword, while another may show a natural inflected or separated form", .maximumCount(2))
    let commonCollocations: [Collocation]

    @Guide(description: "In the learner's native language, at most two short sentences: one truthful retrieval cue, then one common trap with its correction or a tiny active-recall challenge; no unsupported level, frequency, or etymology claims")
    let learningTip: String
}

@available(iOS 26.0, macOS 26.0, *)
@Generable
struct ExampleSentence {
    @Guide(description: "A short, idiomatic sentence in the headword's language that demonstrates the selected sense; the set must include an exact-headword anchor, but another sentence may use a natural inflected or separated form of the same lexeme, never a synonym")
    let sentence: String

    @Guide(description: "Hanyu pinyin with accurate tone marks (ā á ǎ à) exactly matching the sentence when the sentence is Chinese; an EMPTY string when the sentence is English")
    let pinyin: String

    @Guide(description: "When the languages differ, a natural meaning-preserving translation into the learner's native language; when they match, a short plain-language paraphrase that does not duplicate the source sentence")
    let translation: String
}

@available(iOS 26.0, macOS 26.0, *)
@Generable
struct RelatedWord {
    @Guide(description: "The related word, in the same language as the word being explained")
    let word: String

    @Guide(description: "Hanyu pinyin with accurate tone marks exactly matching the word when it is Chinese; an EMPTY string when it is English")
    let pinyin: String

    @Guide(description: "Brief meaning, in the learner's native language")
    let meaning: String

    @Guide(description: "A concrete choice rule in the learner's native language: when to choose the headword and when to choose this alternative")
    let difference: String
}

@available(iOS 26.0, macOS 26.0, *)
@Generable
struct Collocation {
    @Guide(description: "A high-value idiomatic collocation in the headword's language using the selected lexeme; the set must include an exact-headword anchor, but another phrase may use a natural inflected or separated form")
    let phrase: String

    @Guide(description: "Hanyu pinyin with accurate tone marks exactly matching the phrase when it is Chinese; an EMPTY string when it is English")
    let pinyin: String

    @Guide(description: "When the languages differ, a natural translation into the learner's native language; when they match, a short plain-language paraphrase that does not duplicate the source phrase")
    let translation: String
}

/// The single-field result of a translation request.
///
/// Guided generation is the Apple Intelligence equivalent of the JSON envelope
/// the cloud and Ollama paths request: it gives the model exactly one slot for
/// the answer, so a preface, an outline of the passage, or a translator's note
/// has nowhere to land where the app would read it as the translation.
@available(iOS 26.0, macOS 26.0, *)
@Generable
struct TranslationOutput {
    @Guide(description: "The complete translation of the source text into the target language and nothing else: no label, preface, quotation marks, romanization, alternative rendering, note, or commentary. Preserve the source's paragraph breaks.")
    let translation: String
}

/// The single-field result of an OCR cleanup request. Scoped the same way as
/// `TranslationOutput`, because this text becomes the learner's source material
/// for the rest of the photo pipeline.
@available(iOS 26.0, macOS 26.0, *)
@Generable
struct CleanedTextOutput {
    @Guide(description: "The corrected passage in its original language and nothing else: no translation, summary, description, label, heading, or commentary. Keep the passage's own wording, ordering, and paragraph breaks.")
    let text: String
}
#endif

// MARK: - Fallback Models (for when FoundationModels is not available)

/// Fallback struct that mirrors WordExplanation for non-AI scenarios.
/// `Codable` so generated explanations can be persisted in the explanation
/// cache and re-served without another AI round-trip.
struct WordExplanationResult: Equatable, Codable, Sendable {
    let definition: String
    let partOfSpeech: String
    let nuances: String
    let grammarUsage: String
    let usageContexts: [String]
    let exampleSentences: [ExampleSentenceResult]
    let synonyms: [RelatedWordResult]
    let antonyms: [RelatedWordResult]
    let commonCollocations: [CollocationResult]
    let learningTip: String

    static func == (lhs: WordExplanationResult, rhs: WordExplanationResult) -> Bool {
        lhs.definition == rhs.definition && lhs.partOfSpeech == rhs.partOfSpeech
    }
}

/// An example sentence in the word's own language with a translation in the
/// learner's native language. `pinyin` is empty for English sentences.
/// The `id` is a transient view-identity value, regenerated on decode rather
/// than persisted, so it is omitted from the `Codable` keys.
struct ExampleSentenceResult: Identifiable, Equatable, Codable, Sendable {
    let id = UUID()
    let sentence: String
    let pinyin: String
    let translation: String

    private enum CodingKeys: String, CodingKey {
        case sentence, pinyin, translation
    }

    static func == (lhs: ExampleSentenceResult, rhs: ExampleSentenceResult) -> Bool {
        lhs.sentence == rhs.sentence
    }
}

/// A related word (synonym/antonym) in the word's own language with its
/// meaning and usage difference in the learner's native language.
struct RelatedWordResult: Identifiable, Equatable, Codable, Sendable {
    let id = UUID()
    let word: String
    let pinyin: String
    let meaning: String
    let difference: String

    private enum CodingKeys: String, CodingKey {
        case word, pinyin, meaning, difference
    }

    static func == (lhs: RelatedWordResult, rhs: RelatedWordResult) -> Bool {
        lhs.word == rhs.word
    }
}

/// A collocation in the word's own language with a native-language translation.
struct CollocationResult: Identifiable, Equatable, Codable, Sendable {
    let id = UUID()
    let phrase: String
    let pinyin: String
    let translation: String

    private enum CodingKeys: String, CodingKey {
        case phrase, pinyin, translation
    }

    static func == (lhs: CollocationResult, rhs: CollocationResult) -> Bool {
        lhs.phrase == rhs.phrase
    }
}

// MARK: - AI Word Explanation Service

/// Service that uses Apple Intelligence (Foundation Models) to generate detailed
/// word explanations for Mandarin vocabulary learning
@Observable
@MainActor
final class AIWordExplanationService {

    static let shared = AIWordExplanationService()

    /// Cache for generated explanations to avoid repeated API calls
    private var explanationCache: [String: WordExplanationResult] = [:]

    /// Whether the device supports Apple Intelligence
    var isAvailable: Bool {
        #if canImport(FoundationModels)
        guard #available(iOS 26.0, macOS 26.0, *) else { return false }
        return checkAvailability()
        #else
        return false
        #endif
    }

    /// Reason why AI is unavailable (if applicable)
    var unavailabilityReason: String? {
        #if canImport(FoundationModels)
        guard #available(iOS 26.0, macOS 26.0, *) else {
            return "Apple Intelligence requires iOS 26 or later"
        }
        return getUnavailabilityReason()
        #else
        return "Apple Intelligence is not available on this device"
        #endif
    }

    private init() {}

    // MARK: - Availability Check

    #if canImport(FoundationModels)
    @available(iOS 26.0, macOS 26.0, *)
    private func checkAvailability() -> Bool {
        let model = SystemLanguageModel.default
        switch model.availability {
        case .available:
            return true
        case .unavailable:
            return false
        @unknown default:
            return false
        }
    }

    @available(iOS 26.0, macOS 26.0, *)
    private func getUnavailabilityReason() -> String? {
        let model = SystemLanguageModel.default
        switch model.availability {
        case .available:
            return nil
        case .unavailable(let reason):
            switch reason {
            case .deviceNotEligible:
                return "This device does not support Apple Intelligence"
            case .appleIntelligenceNotEnabled:
                return "Apple Intelligence is not enabled. Enable it in Settings > Apple Intelligence & Siri"
            case .modelNotReady:
                return "The AI model is still downloading. Please try again later"
            @unknown default:
                return "Apple Intelligence is currently unavailable"
            }
        @unknown default:
            return "Apple Intelligence is currently unavailable"
        }
    }
    #endif

    // MARK: - Generate Explanation

    /// Generate a detailed explanation for a word or phrase using Apple
    /// Intelligence. The word may be Chinese or English; the explanation is
    /// written in the learner's native language (the interface language).
    /// - Parameters:
    ///   - word: The word or phrase to explain
    ///   - pinyin: Optional pinyin for the word (helps with disambiguation)
    ///   - context: Optional sentence context where the word was encountered
    ///   - bypassCache: When true, evicts and skips the in-memory cache so a
    ///     "Regenerate" request truly re-runs the model instead of instantly
    ///     echoing the previous result back
    /// - Returns: A structured WordExplanationResult with comprehensive information
    func generateExplanation(
        for word: String,
        pinyin: String? = nil,
        context: String? = nil,
        bypassCache: Bool = false
    ) async throws -> WordExplanationResult {
        let direction = ExplanationDirection.current(forWord: word)

        // Check cache first (per direction, so a language toggle regenerates).
        // A forced regeneration evicts the stale entry instead.
        let cacheKey = "\(direction.cacheToken)_\(word)_\(pinyin ?? "")_\(context ?? "")"
        if bypassCache {
            explanationCache.removeValue(forKey: cacheKey)
        } else if let cached = explanationCache[cacheKey] {
            return cached
        }

        #if canImport(FoundationModels)
        guard #available(iOS 26.0, macOS 26.0, *) else {
            throw AIExplanationError.unavailable(reason: String(localized: "Apple Intelligence requires iOS 26 or later"))
        }
        guard isAvailable else {
            throw AIExplanationError.unavailable(reason: unavailabilityReason ?? "Unknown")
        }

        let prompt = AIExplanationPromptBuilder.explanationRequest(
            headword: word,
            pinyin: direction.wordIsChinese ? pinyin : nil,
            context: context
        )

        // Create session with instructions
        let session = LanguageModelSession(
            instructions: AIExplanationPromptBuilder.teacherInstructions(for: direction.promptContext)
        )

        // Generate structured response
        let response = try await session.respond(to: prompt, generating: WordExplanation.self)
        let explanation = response.content

        // Require an exact surface-form anchor, then retain bounded natural
        // inflections/separable forms from the same generated set. Filtering
        // every row by literal substring discarded valid `run/running` and
        // `洗澡/洗了个澡` teaching examples.
        let boundedExamples = Array(explanation.exampleSentences.prefix(3))
        let validExamples = AIExplanationPromptBuilder.hasExactHeadwordAnchor(
            word,
            in: boundedExamples.map(\.sentence)
        ) ? boundedExamples : []
        let boundedCollocations = Array(explanation.commonCollocations.prefix(2))
        let validCollocations = AIExplanationPromptBuilder.hasExactHeadwordAnchor(
            word,
            in: boundedCollocations.map(\.phrase)
        ) ? boundedCollocations : []

        // Convert to result type
        let result = WordExplanationResult(
            definition: explanation.definition,
            partOfSpeech: explanation.partOfSpeech,
            nuances: explanation.nuances,
            grammarUsage: explanation.grammarUsage,
            usageContexts: Array(explanation.usageContexts.prefix(3)),
            exampleSentences: validExamples.map {
                ExampleSentenceResult(sentence: $0.sentence, pinyin: $0.pinyin, translation: $0.translation)
            },
            synonyms: explanation.synonyms.prefix(2).map {
                RelatedWordResult(word: $0.word, pinyin: $0.pinyin, meaning: $0.meaning, difference: $0.difference)
            },
            antonyms: explanation.antonyms.prefix(1).map {
                RelatedWordResult(word: $0.word, pinyin: $0.pinyin, meaning: $0.meaning, difference: $0.difference)
            },
            commonCollocations: validCollocations.map {
                CollocationResult(phrase: $0.phrase, pinyin: $0.pinyin, translation: $0.translation)
            },
            learningTip: explanation.learningTip
        )

        try validateExplanation(result, direction: direction)

        // Cache the result
        explanationCache[cacheKey] = result

        return result
        #else
        throw AIExplanationError.unavailable(reason: "FoundationModels framework not available")
        #endif
    }

    // MARK: - AI Translation

    /// Translate text using Apple Intelligence
    /// - Parameters:
    ///   - text: The text to translate
    ///   - sourceIsChinese: Whether the source text is Chinese (true) or English (false)
    /// - Returns: The translated text
    func translate(_ text: String, sourceIsChinese: Bool) async throws -> String {
        #if canImport(FoundationModels)
        guard #available(iOS 26.0, macOS 26.0, *) else {
            throw AIExplanationError.unavailable(reason: String(localized: "Apple Intelligence requires iOS 26 or later"))
        }
        guard isAvailable else {
            throw AIExplanationError.unavailable(reason: unavailabilityReason ?? "Unknown")
        }

        let prompt = AITranslationPromptBuilder.request(text: text, sourceIsChinese: sourceIsChinese)

        // Create session with translation instructions
        let session = LanguageModelSession(instructions: AITranslationPromptBuilder.instructions)

        // Generate a structured translation. Guided generation is what keeps
        // commentary out of the result; the parser then removes any wrapper the
        // model still put inside the field.
        let response = try await session.respond(to: prompt, generating: TranslationOutput.self)
        let translation = AITranslationResponseParser.sanitizedEnvelopeValue(response.content.translation)
        guard !translation.isEmpty else {
            throw AITranslationResponseError.noTranslation
        }
        return translation
        #else
        throw AIExplanationError.unavailable(reason: "FoundationModels framework not available")
        #endif
    }

    /// Clear the explanation cache
    func clearCache() {
        explanationCache.removeAll()
    }

    /// Get cached explanation if available (Apple Intelligence path; cached
    /// per direction so a language toggle never serves the old language)
    func getCachedExplanation(for word: String, pinyin: String? = nil, context: String? = nil) -> WordExplanationResult? {
        let direction = ExplanationDirection.current(forWord: word)
        let cacheKey = "\(direction.cacheToken)_\(word)_\(pinyin ?? "")_\(context ?? "")"
        return explanationCache[cacheKey]
    }

    // MARK: - Unified AI Methods (Auto-selects provider based on settings)

    /// Generate explanation using the configured AI provider (Apple Intelligence or Ollama)
    /// - Parameters:
    ///   - word: The Chinese word or phrase to explain
    ///   - pinyin: Optional pinyin for the word
    ///   - context: Optional sentence context
    ///   - bypassCache: When true, evicts the in-memory cache entry for this
    ///     request and regenerates (used by the "Regenerate" button, which must
    ///     never be answered from cache)
    /// - Returns: A structured WordExplanationResult
    func generateExplanationWithProvider(
        for word: String,
        pinyin: String? = nil,
        context: String? = nil,
        bypassCache: Bool = false
    ) async throws -> WordExplanationResult {
        let settings = AIModelSettings.shared
        let provider = settings.effectiveProvider

        switch provider {
        case .appleIntelligence:
            return try await generateExplanation(for: word, pinyin: pinyin, context: context, bypassCache: bypassCache)
        case .ollama:
            return try await generateExplanationWithOllama(for: word, pinyin: pinyin, context: context, bypassCache: bypassCache)
        default:
            return try await generateExplanationWithCloud(provider: provider, for: word, pinyin: pinyin, context: context, bypassCache: bypassCache)
        }
    }

    /// Translate text using the configured AI provider
    /// - Parameters:
    ///   - text: The text to translate
    ///   - sourceIsChinese: Whether the source is Chinese
    /// - Returns: The translated text
    func translateWithProvider(_ text: String, sourceIsChinese: Bool) async throws -> String {
        let settings = AIModelSettings.shared
        // On systems without Apple's Translation API this is the only
        // translation backend, so fail with actionable guidance.
        guard settings.isAnyProviderAvailable else {
            throw AIExplanationError.unavailable(
                reason: String(localized: "No AI provider is configured. Add one in Settings → AI (or run a local Ollama server).")
            )
        }
        let provider = settings.effectiveProvider

        switch provider {
        case .appleIntelligence:
            return try await translate(text, sourceIsChinese: sourceIsChinese)
        case .ollama:
            return try await translateWithOllama(text, sourceIsChinese: sourceIsChinese)
        default:
            let model = settings.selectedModel(for: provider)
            guard !settings.apiKey(for: provider).isEmpty else {
                throw AIExplanationError.unavailable(reason: "No API key for \(provider.displayName)")
            }
            return try await CloudAIService.shared.translate(
                text, sourceIsChinese: sourceIsChinese, provider: provider, model: model
            )
        }
    }

    // MARK: - Ollama-Specific Methods

    /// Generate a word explanation using Ollama
    private func generateExplanationWithOllama(
        for word: String,
        pinyin: String? = nil,
        context: String? = nil,
        bypassCache: Bool = false
    ) async throws -> WordExplanationResult {
        let settings = AIModelSettings.shared

        guard OllamaService.shared.isConnected else {
            throw AIExplanationError.ollamaNotConnected
        }

        guard !settings.ollamaModel.isEmpty else {
            throw AIExplanationError.ollamaNoModelSelected
        }

        let direction = ExplanationDirection.current(forWord: word)

        // Check cache first (per direction, so a language toggle regenerates).
        // A forced regeneration evicts the stale entry instead.
        let cacheKey = "ollama_\(direction.cacheToken)_\(word)_\(pinyin ?? "")_\(context ?? "")"
        if bypassCache {
            explanationCache.removeValue(forKey: cacheKey)
        } else if let cached = explanationCache[cacheKey] {
            return cached
        }

        let prompt = AIExplanationPromptBuilder.explanationRequest(
            headword: word,
            pinyin: direction.wordIsChinese ? pinyin : nil,
            context: context
        )

        let native = direction.explanationLanguageName
        let wordLang = direction.wordLanguageName
        let pinyinDesc: Ollama.Value = direction.wordIsChinese
            ? "Hanyu pinyin with tone marks (ā á ǎ à) exactly matching the text"
            : "Empty string (the text is English)"
        let sameLanguage = direction.wordIsChinese == direction.explainInChinese
        let definitionDesc: Ollama.Value = sameLanguage
            ? "Non-circular plain-language definition or paraphrase plus semantic essence in \(native), at most two short sentences"
            : "Closest natural translation plus semantic essence in \(native), at most two short sentences"
        let renderingDesc: Ollama.Value = sameLanguage
            ? "Short plain-language paraphrase in \(native), never a duplicate of the source text"
            : "Natural meaning-preserving translation into \(native), not a rigid gloss"
        let nuancesDesc: Ollama.Value = direction.wordIsChinese
            ? "One compact line per character or morpheme and its honest semantic, phonetic, transliterated, grammatical, fossilized, or uncertain role; a localized Together bridge to the whole; then register, feeling, and a practical contrast, in \(native); never invent etymology"
            : "Genuine morphology only when useful; otherwise register, feeling, and a practical contrast in \(native), without repeating the definition"

        // JSON schema for structured output (direction-aware descriptions)
        let schema: Ollama.Value = [
            "type": "object",
            "properties": [
                "definition": ["type": "string", "description": definitionDesc],
                "partOfSpeech": ["type": "string", "description": "Precise part of speech for the selected sense, with relevant behavior, in \(native)"],
                "nuances": ["type": "string", "description": nuancesDesc],
                "grammarUsage": ["type": "string", "description": "Only actionable grammar and a reusable construction in \(native); empty when no special rule applies"],
                "usageContexts": [
                    "type": "array",
                    "items": ["type": "string"],
                    "description": "2-3 concrete mini-situations where a native speaker would choose this sense, in \(native)"
                ],
                "exampleSentences": [
                    "type": "array",
                    "items": [
                        "type": "object",
                        "properties": [
                            "sentence": ["type": "string", "description": "Short idiomatic \(wordLang) use of the selected lexeme; the set needs one exact-headword anchor and may also show a natural inflected or separated form"],
                            "pinyin": ["type": "string", "description": pinyinDesc],
                            "translation": ["type": "string", "description": renderingDesc]
                        ],
                        "required": ["sentence", "pinyin", "translation"]
                    ],
                    "description": "1-2 semantically distinct examples; a third only for a genuinely different construction"
                ],
                "synonyms": [
                    "type": "array",
                    "items": [
                        "type": "object",
                        "properties": [
                            "word": ["type": "string", "description": "Genuine near-synonym in \(wordLang)"],
                            "pinyin": ["type": "string", "description": pinyinDesc],
                            "meaning": ["type": "string", "description": "Meaning in \(native)"],
                            "difference": ["type": "string", "description": "Concrete choice rule between it and the headword, in \(native)"]
                        ],
                        "required": ["word", "pinyin", "meaning", "difference"]
                    ],
                    "description": "0-2 high-confidence near-synonyms; empty is better than an invented relation"
                ],
                "antonyms": [
                    "type": "array",
                    "items": [
                        "type": "object",
                        "properties": [
                            "word": ["type": "string", "description": "Opposite word in \(wordLang)"],
                            "pinyin": ["type": "string", "description": pinyinDesc],
                            "meaning": ["type": "string", "description": "Meaning in \(native)"],
                            "difference": ["type": "string", "description": "Usage difference, in \(native)"]
                        ],
                        "required": ["word", "pinyin", "meaning", "difference"]
                    ],
                    "description": "0-1 established lexical opposite; empty when none exists"
                ],
                "commonCollocations": [
                    "type": "array",
                    "items": [
                        "type": "object",
                        "properties": [
                            "phrase": ["type": "string", "description": "High-value idiomatic \(wordLang) phrase using the selected lexeme; the set needs one exact-headword anchor and may also show a natural inflected or separated form"],
                            "pinyin": ["type": "string", "description": pinyinDesc],
                            "translation": ["type": "string", "description": renderingDesc]
                        ],
                        "required": ["phrase", "pinyin", "translation"]
                    ],
                    "description": "0-2 high-confidence reusable collocations; never pad the list"
                ],
                "learningTip": ["type": "string", "description": "At most two short sentences in \(native): a truthful retrieval cue plus one correction or active-recall prompt; no unsupported level, frequency, or etymology claims"]
            ],
            "required": ["definition", "partOfSpeech", "nuances", "grammarUsage", "usageContexts", "exampleSentences", "synonyms", "commonCollocations", "learningTip"]
        ]

        let jsonString = try await OllamaService.shared.generateStructured(
            model: settings.ollamaModel,
            systemPrompt: AIExplanationPromptBuilder.teacherInstructions(for: direction.promptContext),
            userPrompt: prompt,
            schema: schema,
            enableThinking: settings.enableThinking
        )

        // Parse JSON response
        guard let data = jsonString.data(using: .utf8) else {
            throw AIExplanationError.generationFailed("Invalid UTF-8 response")
        }

        let response = try JSONDecoder().decode(OllamaWordExplanationResponse.self, from: data)
        let result = response.toResult(filteringFor: word)
        try validateExplanation(result, direction: direction)

        // Cache the result
        explanationCache[cacheKey] = result

        return result
    }

    /// Translate text using Ollama
    private func translateWithOllama(_ text: String, sourceIsChinese: Bool) async throws -> String {
        let settings = AIModelSettings.shared

        guard OllamaService.shared.isConnected else {
