        NavigationStack {
            GeometryReader { geometry in
                ScrollView {
                    VStack(spacing: 0) {
                        // Direction toggle
                        directionToggle
                            .padding(.horizontal)
                            .padding(.top, 8)

                        // Source input section
                        sourceInputSection
                            .frame(minHeight: geometry.size.height * 0.35)

