    }

    // MARK: OCR cleanup shares the contract

    try expectValue(
        AITextCleanupResponseParser.cleanedText(from: "{\"text\":\"梁文锋在演讲中说…\"}"),
        "梁文锋在演讲中说…",
        "OCR cleanup reads its own one-field envelope"
