            .sheet(isPresented: $showCameraScanner) {
                CameraScannerSheet(capturedText: $capturedText)
                    .localizedSurface()
            }
            .sheet(item: $selectedEnglishWord) { word in
                EnglishWordDetailSheet(word: word)
                    .localizedSurface()
            }
            .sheet(item: $selectedChineseSegment) { segment in
                WordDetailPopover(
                    segment: segment,
