    let pinyin = headwordIsChinese
        ? (term.reading.isEmpty ? PinyinConverter.convert(headword) : term.reading)
        : ""
    savedTermsStore.add(SavedTerm(
        chinese: headword,
        pinyin: pinyin,
        definition: term.meaning,
        partOfSpeech: "phrase"
    ))
}

