            )

            // Save all words button
            Button {
                Task {
                    await saveAllChineseWordsToVocabulary()
                }
            } label: {
                Label("保存所有词汇到词汇本", systemImage: "bookmark")
                    .fitSingleLine()
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.bordered)
        }
    }

